html:
{%- set emp = frappe.db.get_value("Employee", doc.employee,
    ["employee_name","designation","department"], as_dict=True) or {} %}
{%- set mgr = frappe.db.get_value("Employee", doc.manager,
    ["employee_name","designation"], as_dict=True) or {} %}
<!DOCTYPE html><html><head><meta charset="UTF-8"/>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; color: #1E293B; }
.page-header { background: linear-gradient(135deg, #1E2D5A 0%, #5B2D8E 100%);
  padding: 24px 32px; color: white; display: flex;
  justify-content: space-between; align-items: flex-start; }
.brand { font-size: 18pt; font-weight: 900; letter-spacing: -1px; }
.brand-sub { font-size: 8pt; color: rgba(255,255,255,.65); margin-top: 2px; }
.doc-meta { text-align: right; }
.doc-meta h1 { font-size: 14pt; font-weight: 800; }
.doc-meta p  { font-size: 8pt; color: rgba(255,255,255,.7); margin-top: 3px; }
.emp-band { background:#F1F5F9; border-left:5px solid #5B2D8E;
  padding:12px 32px; display:flex; gap:28px; flex-wrap:wrap; }
.ef .el { font-size:8pt; font-weight:700; color:#64748B;
  text-transform:uppercase; letter-spacing:.4px; }
.ef .ev { font-size:10pt; font-weight:600; margin-top:2px; }
.sec { padding:14px 32px; border-bottom:1px solid #E5E7EB; }
.sec-h { font-size:10pt; font-weight:800; color:#5B2D8E; text-transform:uppercase;
  letter-spacing:.5px; border-bottom:2px solid #5B2D8E; padding-bottom:5px;
  margin-bottom:10px; }
table { width:100%; border-collapse:collapse; margin:6px 0; }
th { background:#1E2D5A; color:white; padding:7px 10px;
  font-size:8.5pt; font-weight:700; text-align:left; }
td { padding:7px 10px; font-size:9.5pt; border-bottom:1px solid #F1F5F9; }
tr:nth-child(even) td { background:#F8FAFC; }
.nb { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:5px;
  padding:10px 14px; min-height:50px; font-size:9.5pt; line-height:1.6;
  white-space:pre-wrap; }
.pill { display:inline-block; padding:2px 10px; border-radius:99px;
  font-weight:700; font-size:8.5pt; }
.green { background:#D1FAE5; color:#065F46; }
.blue  { background:#DBEAFE; color:#1D4ED8; }
.amber { background:#FEF3C7; color:#92400E; }
.red   { background:#FEE2E2; color:#991B1B; }
.purple{ background:#EDE9FE; color:#5B21B6; }
.score-hero { text-align:center; background:#F0FDF4;
  border:2px solid #6EE7B7; border-radius:10px; padding:14px; margin:8px 0; }
.score-num { font-size:30pt; font-weight:900; color:#059669; }
.score-lbl { font-size:9pt; color:#6B7280; }
.sig-row { display:flex; gap:28px; margin-top:6px; }
.sig-box { flex:1; }
.sig-line { border-bottom:1.5px solid #1E2D5A; margin-top:28px; margin-bottom:5px; }
.sig-name { font-size:8.5pt; color:#6B7280; }
.page-footer { background:#F8FAFC; border-top:1px solid #E2E8F0;
  padding:8px 32px; display:flex; justify-content:space-between;
  font-size:7.5pt; color:#94A3B8; }

.rec-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin:8px 0; }
.rec-card { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:6px;
  padding:10px 14px; }
.rec-label { font-size:8pt; font-weight:700; color:#64748B; text-transform:uppercase; }
.rec-value { font-size:10pt; font-weight:600; margin-top:3px; }
.warn-box { background:#FEF3C7; border:1px solid #FDE68A; border-radius:6px;
  padding:10px 14px; font-size:9pt; color:#92400E; margin-top:8px; }
</style></head><body>

<div class="page-header">
  <div><div class="brand">Ecclesia</div><div class="brand-sub">360° Performance Management</div></div>
  <div class="doc-meta"><h1>Manager Review 360</h1>
    <p>{{ doc.performance_cycle }}</p>
    <p>{{ doc.name }} | {{ frappe.format_date(doc.review_date or doc.creation) }}</p></div>
</div>

<div class="emp-band">
  <div class="ef"><div class="el">Employee</div><div class="ev">{{ emp.employee_name or doc.employee }}</div></div>
  <div class="ef"><div class="el">Designation</div><div class="ev">{{ emp.designation or "—" }}</div></div>
  <div class="ef"><div class="el">Department</div><div class="ev">{{ emp.department or "—" }}</div></div>
  <div class="ef"><div class="el">Reviewed By</div><div class="ev">{{ mgr.employee_name or doc.manager }}</div></div>
  <div class="ef"><div class="el">Review Date</div><div class="ev">{{ frappe.format_date(doc.review_date or doc.creation) }}</div></div>
</div>

<!-- SCORE SUMMARY -->
<div class="sec">
  <div class="sec-h">📊 Score Summary</div>
  <div class="rec-grid">
    {% for label, field, color in [
      ("Goal / KPI Score", "goal_score", "green"),
      ("Competency Score", "competency_score", "blue"),
      ("Values Score", "values_score", "purple"),
      ("Overall Rating", "overall_manager_rating", "green")] %}
    <div class="rec-card">
      <div class="rec-label">{{ label }}</div>
      <div class="rec-value">
        <span class="pill {{ color }}">{{ doc.get(field) or "—" }} / 5</span>
      </div>
    </div>
    {% endfor %}
  </div>
</div>

{% if doc.competency_ratings %}
<div class="sec">
  <div class="sec-h">🧠 Competency Assessment</div>
  <table><thead><tr><th>Competency</th><th>Category</th><th>Rating</th><th>Observations</th></tr></thead>
  <tbody>{% for r in doc.competency_ratings %}<tr>
    <td><b>{{ r.competency }}</b></td><td>{{ r.category or "—" }}</td>
    <td><span class="pill {% if r.manager_rating|int >= 4 %}green{% elif r.manager_rating|int == 3 %}blue{% else %}amber{% endif %}">{{ r.manager_rating }}/5</span></td>
    <td>{{ r.observations or "—" }}</td>
  </tr>{% endfor %}</tbody></table>
</div>
{% endif %}

{% if doc.overall_assessment %}
<div class="sec"><div class="sec-h">📝 Overall Assessment</div>
  <div class="nb">{{ doc.overall_assessment }}</div></div>
{% endif %}

{% if doc.strengths %}
<div class="sec"><div class="sec-h">✅ Key Strengths</div>
  <div class="nb">{{ doc.strengths }}</div></div>
{% endif %}

{% if doc.improvement_areas %}
<div class="sec"><div class="sec-h">📈 Areas for Improvement</div>
  <div class="nb">{{ doc.improvement_areas }}</div></div>
{% endif %}

<!-- HR RECOMMENDATIONS -->
<div class="sec">
  <div class="sec-h">🏆 HR Recommendations</div>
  <div class="rec-grid">
    <div class="rec-card">
      <div class="rec-label">Promotion</div>
      <div class="rec-value">{% if doc.recommend_promotion %}<span class="pill green">✓ Recommended</span>{% else %}<span class="pill amber">Not Recommended</span>{% endif %}</div>
    </div>
    <div class="rec-card">
      <div class="rec-label">Salary Increment</div>
      <div class="rec-value">{% if doc.recommend_increment %}<span class="pill green">✓ {{ doc.increment_percentage or "" }}%</span>{% else %}<span class="pill amber">Not Recommended</span>{% endif %}</div>
    </div>
    <div class="rec-card">
      <div class="rec-label">Training</div>
      <div class="rec-value">{% if doc.recommend_training %}<span class="pill blue">✓ Required</span>{% else %}—{% endif %}</div>
    </div>
    <div class="rec-card">
      <div class="rec-label">PIP Required</div>
      <div class="rec-value">{% if doc.recommend_pip %}<span class="pill red">⚠ PIP Recommended</span>{% else %}—{% endif %}</div>
    </div>
  </div>
  {% if doc.recommend_pip and doc.pip_reason %}
  <div class="warn-box">⚠️ PIP Reason: {{ doc.pip_reason }}</div>
  {% endif %}
</div>

<div class="sec"><div class="sec-h">✍️ Signatures</div>
  <div class="sig-row">
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>{{ mgr.employee_name or doc.manager }}</b><br>Reviewing Manager</div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>{{ emp.employee_name or doc.employee }}</b><br>Employee (Acknowledged)</div></div>
    <div class="sig-box"><div class="sig-line"></div>
      <div class="sig-name"><b>HR Representative</b><br>Verified By</div></div>
  </div>
</div>

<div class="page-footer">
  <span>Ecclesia HR · Value Impacts Consulting</span>
  <span>{{ doc.name }} | Printed: {{ frappe.format_date(frappe.utils.nowdate()) }}</span>
  <span>CONFIDENTIAL</span>
</div>
</body></html>
